// ---- js/bazaar-core.js
const m_bazaar_core = await (async () => {
const DATA = m_bazaar_data;
// 《弥萨格大巴扎》核心逻辑：商店、布阵、自动战斗。
// 不碰 DOM，node 里能直接跑（scripts/bazaar-sim.mjs 就是拿它做平衡实测的）。
//
// 一场战斗的心跳是「拍」（beat）：造物按冷却排期，到点就触发，
// 双方同时走；谁先归零谁输，40 拍打不完算输。



// 这里的 build.mjs 只认 export const/let/function/class（没有 export {...} 重导出），
// 所以对外重新声明一遍，模拟脚本和界面都从这里拿。
const TUNING = DATA.TUNING;
const HEROES = DATA.HEROES;
const ITEMS = DATA.ITEMS;
const WHEELS = DATA.WHEELS;
const WHEEL_FX = DATA.WHEEL_FX;
const PACTS = DATA.PACTS;
const FOES = DATA.FOES;
const SCHEDULE = DATA.SCHEDULE;

const DOT_TURNS = 3;
const ITEM_BY_ID = new Map(ITEMS.map((x) => [x.id, x]));
const WHEEL_BY_ID = new Map(WHEELS.map((x) => [x.id, x]));
const FOE_BY_ID = new Map(FOES.map((x) => [x.id, x]));
const HERO_BY_ID = new Map(HEROES.map((x) => [x.id, x]));
const PACT_BY_ID = new Map(PACTS.map((x) => [x.id, x]));

const itemOf = (id) => ITEM_BY_ID.get(id);
const wheelOf = (id) => WHEEL_BY_ID.get(id);
const foeOf = (id) => FOE_BY_ID.get(id);
const heroOf = (id) => HERO_BY_ID.get(id);
const pactOf = (id) => PACT_BY_ID.get(id);

// 相邻：2 行 × 3 列，上下左右算相邻
const ADJ = [
  [1, 3], [0, 2, 4], [1, 5],
  [0, 4], [1, 3, 5], [2, 4],
];

function rngFrom(seed) {
  let a = seed >>> 0;
  return function rnd() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const ru = (rnd, arr) => arr[Math.floor(rnd() * arr.length) % arr.length];
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

let UID = 1;
const mkItem = (key, tier = 1) => ({ uid: UID++, key, tier });

function newRun({ seed = Date.now() >>> 0, heroId, pactId, totalDays = 12 } = {}) {
  const hero = heroOf(heroId) || HEROES[0];
  const pact = pactOf(pactId) || PACTS[0];
  const run = {
    seed, rnd: rngFrom(seed), hero, pact, totalDays,
    day: 1, sane: TUNING.sane, gold: TUNING.startGold,
    items: new Array(TUNING.slotN).fill(null),
    wheels: [],
    shop: [], rerolls: 0,
    foeId: null, wins: 0, losses: 0,
    bonusHp: 0,            // 光合祭礼之类的永久加血
    over: false, cleared: false,
    history: [],
  };
  if (pact.k === 'rich') run.gold += pact.v;
  hero.kit.forEach((k, i) => { run.items[i] = mkItem(k, 1); });
  // 本命命轮：直接戴在身上，白送一个词条
  run.wheels.push({ uid: UID++, key: 'native' + hero.id, native: true, n: hero.wheel.n, im: hero.wheel.im, main: hero.wheel.main, cost: 0 });
  pickFoe(run);
  rollShop(run, { free: true });
  return run;
}

// ---------------------------------------------------------------- 商店
function priceOf(run, base) {
  const p = run.pact.k === 'discount' ? 1 - run.pact.v : 1;
  return Math.max(1, Math.round(base * p));
}

function pickRarity(run, rnd) {
  const d = run.day;
  const wN = Math.max(2, 12 - d * 1.3);
  const wSR = 2 + d * 0.75;
  const wSSR = Math.max(0, d - 3) * 0.85;
  const tot = wN + wSR + wSSR;
  const x = rnd() * tot;
  if (x < wSSR) return 'SSR';
  if (x < wSSR + wSR) return 'SR';
  return 'N';
}

function rollShop(run, { free = false } = {}) {
  const rnd = run.rnd;
  if (!free) {
    const cost = TUNING.rerollCost + run.rerolls;
    if (run.gold < cost) return false;
    run.gold -= cost;
    run.rerolls += 1;
  }
  const n = 4 + (run.pact.k === 'rich' && run.day === 1 ? 1 : 0);
  const out = [];
  const used = new Set();
  for (let i = 0; i < n; i++) {
    let offer = null;
    for (let tries = 0; tries < 12 && !offer; tries++) {
      if (rnd() < 0.22) {
        const w = ru(rnd, WHEELS);
        if (used.has('w' + w.id)) continue;
        used.add('w' + w.id);
        offer = { kind: 'wheel', key: w.id, price: priceOf(run, w.cost) };
      } else {
        const r = pickRarity(run, rnd);
        const pool = ITEMS.filter((x) => x.r === r);
        const it = ru(rnd, pool);
        if (used.has(it.id)) continue;
        used.add(it.id);
        offer = { kind: 'item', key: it.id, price: priceOf(run, it.cost) };
      }
    }
    if (offer) { offer.sold = false; out.push(offer); }
  }
  run.shop = out;
  run.rerolls = 0;
  return true;
}

function defOf(offer) {
  return offer.kind === 'wheel' ? wheelOf(offer.key) : itemOf(offer.key);
}

function firstEmptySlot(run) {
  return run.items.findIndex((x) => !x);
}

function canBuy(run, idx) {
  const o = run.shop[idx];
  if (!o || o.sold) return false;
  if (run.gold < o.price) return false;
  if (o.kind === 'wheel') return run.wheels.length < 3;
  return firstEmptySlot(run) >= 0;
}

function buy(run, idx) {
  if (!canBuy(run, idx)) return false;
  const o = run.shop[idx];
  run.gold -= o.price;
  o.sold = true;
  if (o.kind === 'wheel') run.wheels.push({ uid: UID++, key: o.key, ...wheelOf(o.key) });
  else run.items[firstEmptySlot(run)] = mkItem(o.key, 1);
  return true;
}

function sell(run, uid) {
  for (let i = 0; i < run.items.length; i++) {
    const it = run.items[i];
    if (it && it.uid === uid) {
      const def = itemOf(it.key);
      const back = Math.max(1, Math.floor(def.cost * TUNING.sellRate * TUNING.tierMul[it.tier]));
      run.items[i] = null;
      run.gold += back;
      return back;
    }
  }
  const w = run.wheels.findIndex((x) => x.uid === uid);
  if (w >= 0 && !run.wheels[w].native) {
    const back = Math.max(1, Math.floor(run.wheels[w].cost * TUNING.sellRate));
    run.gold += back;
    run.wheels.splice(w, 1);
    return back;
  }
  return 0;
}

function upgradeCost(run, it) {
  return TUNING.upgradeCost + (it.tier - 1) * 5;
}

function upgrade(run, uid) {
  const it = run.items.find((x) => x && x.uid === uid);
  if (!it || it.tier >= 3) return false;
  const c = upgradeCost(run, it);
  if (run.gold < c) return false;
  run.gold -= c;
  it.tier += 1;
  return true;
}

// 把 a 槽的东西挪到 b 槽；b 槽有东西就交换；同款同阶则合并升阶
function move(run, a, b) {
  if (a === b) return 'noop';
  const A = run.items[a], B = run.items[b];
  if (!A) return 'noop';
  if (B && B.key === A.key && B.tier === A.tier && A.tier < 3) {
    run.items[b] = { ...B, uid: B.uid, tier: B.tier + 1 };
    run.items[a] = null;
    return 'merge';
  }
  run.items[a] = B;
  run.items[b] = A;
  return 'swap';
}

// ---------------------------------------------------------------- 对手
function pickFoe(run, day = run.day) {
  const row = SCHEDULE.find((x) => x.day === day) || SCHEDULE[SCHEDULE.length - 1];
  const id = ru(run.rnd, row.pool);
  run.foeId = id;
  return FOE_BY_ID.get(id);
}

// 一只怪技能表折算出来的「每拍输出」（不含当天系数），用来把同一天的不同怪拉到同一档。
// 权重是经验值：中毒/灼烧按持续结算打折，护盾/治疗按等效血量折算。
// 中毒/灼烧是「3 拍内每拍掉 v 点」的持续伤害，等效总量 3v；折成每拍才好和其他技能相加。
function rawDps(foe) {
  let d = 0;
  for (const s of foe.skills) {
    let per = 0;
    for (const op of s.op) {
      if (op.k === 'dmg') per += (op.v || 0) * (op.hits || 1);
      else if (op.k === 'poison' || op.k === 'burn') per += (op.v || 0) * 3;
    }
    d += per / Math.max(1, s.cd);
  }
  return Math.max(0.6, d);
}

// 会自愈/架盾的怪等于多了一大截血。这里把「撑住的血」从生命预算里扣掉，
// 否则一只治疗怪既有满额输出又打不死，同一天里它就成了必败场。
const supDps = (foe) => {
  let d = 0;
  for (const s of foe.skills) {
    let per = 0;
    for (const op of s.op) {
      if (op.k === 'heal') per += op.v * 0.9;
      else if (op.k === 'shield') per += op.v * 0.7;
    }
    d += per / Math.max(1, s.cd);
  }
  return d;
};

function foeStats(run, day = run.day) {
  const foe = FOE_BY_ID.get(run.foeId) || FOES[0];
  const row = SCHEDULE.find((x) => x.day === day) || SCHEDULE[SCHEDULE.length - 1];
  const weaken = run.pact.k === 'weaken' ? 1 - run.pact.v : 1;
  const rankMul = row.boss && foe.rank !== 'boss' ? 1.06 : 1;
  const hpMul = foe.rank === 'boss' ? 1.12 : 1;
  const sup = 1 + (day - 1) * 0.2;
  const budget = TUNING.dayHp[day] * weaken * rankMul * hpMul;
  const sustain = supDps(foe) * sup * 22;
  return {
    foe,
    maxHp: Math.round(Math.max(budget * 0.55, budget - sustain)),
    // 起手要等冷却、收尾常常差半拍，实测三成左右的输出落在战斗之外；
    // 乘回去之后 dayDps 才真的等于「这只怪每拍打掉多少」。
    atk: (TUNING.dayDps[day] / rawDps(foe)) * 1.38,
    sup,
    boss: foe.rank === 'boss',
  };
}

// ---------------------------------------------------------------- 战斗
function createFight(run) {
  const { foe, maxHp, atk, sup } = foeStats(run);
  const hero = run.hero;
  const pact = run.pact;

  // 汇总全局修正
  const mod = { amp: 0, crit: 0.1, cdmg: 0.5, regen: 0, gold: 0, flat: 0, hp: 0, ward: 0, leech: 0, cdDown: 0, openShield: 0 };
  const addWheel = (main) => {
    const fx = WHEEL_FX[main];
    if (!fx) return;
    for (const k of ['amp', 'crit', 'cdmg', 'regen', 'gold', 'flat', 'hp', 'ward']) if (fx[k]) mod[k] += fx[k];
  };
  addWheel(hero.wheel.main);
  for (const w of run.wheels) if (!w.native) addWheel(w.main);

  if (hero.pas.k === 'amp') mod.amp += hero.pas.v;
  if (hero.pas.k === 'tide') mod.hp += hero.pas.v;
  if (hero.pas.k === 'bulwark') mod.hp += 0;
  if (pact.k === 'cddown') mod.cdDown = pact.v;
  if (pact.k === 'leech') mod.leech = pact.v;
  if (pact.k === 'openshield') mod.openShield = pact.v;

  const maxHP = TUNING.startHp + mod.hp + run.bonusHp;
  const f = {
    t: 0, over: null, win: false,
    p: { hp: maxHP, maxHp: maxHP, shield: 0, poison: 0, poisonT: 0, burn: 0, burnT: 0 },
    e: {
      hp: maxHp, maxHp, shield: 0, poison: 0, poisonT: 0, burn: 0, burnT: 0, name: foe.n, im: foe.im, rank: foe.rank,
      skills: foe.skills.map((s) => ({ n: s.n, cd: s.cd, timer: 0, op: s.op })),
      slow: 0,
    },
    items: [], slotOf: [], gold: 0, firstDone: false,
    mod, hero, pact, foe,
    atkMul: atk, supMul: sup, rnd: run.rnd, pw: 1,
    shieldCap: 60 + (hero.pas.k === 'bulwark' ? hero.pas.v : 0),
    surgeT: 0, wardT: 0, saveUsed: false,
    dealt: 0, taken: 0,
  };

  // 造物实例（含相邻光环、冷却）
  const live = [];
  run.items.forEach((it, slot) => {
    if (!it) return;
    const def = itemOf(it.key);
    const mul = TUNING.tierMul[it.tier] || 1;
    live.push({ slot, def, tier: it.tier, mul, timer: 0, cd: def.cd, aura: 0 });
  });
  // 相邻光环：光环造物只加成相邻的
  for (const a of live) {
    if (a.def.cd > 0) continue;
    for (const nb of ADJ[a.slot]) {
      const b = live.find((x) => x.slot === nb);
      if (b) b.aura += (a.def.op[0].v || 0) * a.mul;
    }
  }
  // 冷却：密契减 1、拉蒙娜开局先走 2 拍
  for (const a of live) if (a.cd > 0) {
    a.cd = Math.max(2, a.cd - mod.cdDown);
    if (hero.pas.k === 'tempo') a.timer = Math.min(a.cd, hero.pas.v);
  }
  f.items = live;

  if (mod.openShield) f.p.shield = Math.min(f.shieldCap, mod.openShield);
  return f;
}

function damageTo(target, amount) {
  const sh = Math.min(target.shield, amount);
  target.shield -= sh;
  target.hp -= amount - sh;
  return amount - sh;
}

function hurt(f, target, amount) {
  if (target === f.p && f.hero.pas.k === 'bulwark' && f.p.shield > 0) amount *= 0.8;
  if (target === f.p) f.taken += amount;
  return damageTo(target, amount);
}

// 一方的伤害倍率：玩家吃暴击/增伤，敌人吃当天的 atk 系数
function rollDamage(f, side, base) {
  if (side === 'e') return { raw: base, crit: false };
  let raw = base * (1 + f.mod.amp);
  const crit = f.rnd() < f.mod.crit;
  if (crit) raw *= 1.5 + f.mod.cdmg;
  if (side === 'p' && f.hero.pas.k === 'bulwark' && f.p.shield > 0) raw *= 1;
  return { raw, crit };
}

function applyOp(f, side, op, mul, ctx = {}) {
  const ev = [];
  const src = ctx.src || {};
  const e = f.e, p = f.p;
  const target = side === 'p' ? e : p;
  const self = side === 'p' ? p : e;

  switch (op.k) {
    case 'dmg': {
      const hits = op.hits || 1;
      let total = 0;
      let anyCrit = false;
      for (let h = 0; h < hits; h++) {
        const { raw, crit } = rollDamage(f, side, op.v * mul + (ctx.aura || 0) + (side === 'p' ? f.mod.flat : 0));
        if (op.pierce) target.hp -= raw; else hurt(f, target, raw);
        total += raw;
        anyCrit = anyCrit || crit;
      }
      if (op.vsPoison && target.poison > 0) {
        const extra = op.vsPoison * mul;
        hurt(f, target, extra);
        total += extra;
      }
      if (side === 'p') {
        f.dealt += total;
        const leech = (op.leech || 0) + f.mod.leech;
        if (leech > 0) {
          const h = Math.round(total * leech);
          if (h > 0) { self.hp = Math.min(self.maxHp, self.hp + h); ev.push({ s: 'p', k: 'heal', v: h }); }
        }
      }
      ev.push({ s: side, k: 'dmg', v: Math.round(total), hits, crit: anyCrit, slot: src.slot });
      break;
    }
    case 'poison': {
      let v = op.v * mul;
      if (side === 'p' && f.hero.pas.k === 'venom') v += 1;
      target.poison = Math.max(target.poison, v);
      target.poisonT = DOT_TURNS;
      ev.push({ s: side, k: 'poison', v, slot: src.slot });
      break;
    }
    case 'burn': {
      const v = op.v * mul;
      target.burn = Math.max(target.burn, v);
      target.burnT = DOT_TURNS;
      ev.push({ s: side, k: 'burn', v, slot: src.slot });
      break;
    }
    case 'shield': {
      const v = op.v * mul;
      self.shield = Math.min(side === 'p' ? f.shieldCap : 40, self.shield + v);
      ev.push({ s: side, k: 'shield', v, slot: src.slot });
      break;
    }
    case 'heal': {
      const v = Math.round(op.v * mul);
      self.hp = Math.min(self.maxHp, self.hp + v);
      ev.push({ s: side, k: 'heal', v, slot: src.slot });
      break;
    }
    case 'gold': {
      if (side === 'p') { f.gold += Math.round(op.v * mul); ev.push({ s: 'p', k: 'gold', v: Math.round(op.v * mul), slot: src.slot }); }
      break;
    }
    case 'slow': {
      if (side === 'p') {
        const add = Math.min(3 - f.e.slow, op.v * mul);
        if (add > 0) {
          f.e.slow += add;
          for (const s of f.e.skills) s.cd += add;
          ev.push({ s: 'p', k: 'slow', v: add, slot: src.slot });
        }
      }
      break;
    }
    case 'haste': {
      if (side === 'p') {
        for (const nb of ADJ[src.slot] || []) {
          const it = f.items.find((x) => x.slot === nb && x.cd > 0);
          if (it) it.cd = Math.max(2, it.cd - op.v);
        }
        ev.push({ s: 'p', k: 'haste', v: op.v, slot: src.slot, adj: ADJ[src.slot] });
      }
      break;
    }
    case 'charge': {
      if (side === 'p') {
        for (const nb of ADJ[src.slot] || []) {
          const it = f.items.find((x) => x.slot === nb && x.cd > 0);
          if (it) it.timer += op.v * mul;
        }
        ev.push({ s: 'p', k: 'charge', v: op.v, slot: src.slot, adj: ADJ[src.slot] });
      }
      break;
    }
    default: break;
  }
  return ev;
}

// 走一拍，返回这一拍的动画事件
function stepFight(f) {
  const ev = [];
  if (f.over) return ev;
  f.t += 1;

  // 1) 被动
  if (f.hero.pas.k === 'ward' && f.t % f.hero.pas.v === 0) {
    f.p.shield = Math.min(f.shieldCap, f.p.shield + 8);
    ev.push({ s: 'p', k: 'shield', v: 8, pas: 1 });
  }
  if (f.hero.pas.k === 'tide' && f.p.hp < f.p.maxHp * 0.5) {
    f.p.hp = Math.min(f.p.maxHp, f.p.hp + 1);
    ev.push({ s: 'p', k: 'heal', v: 1, pas: 1 });
  }
  if (f.mod.regen) {
    f.p.hp = Math.min(f.p.maxHp, f.p.hp + f.mod.regen);
    if (f.mod.regen >= 1) ev.push({ s: 'p', k: 'heal', v: f.mod.regen, pas: 1 });
  }
  if (f.mod.ward && f.t % 4 === 0) {
    f.p.shield = Math.min(f.shieldCap, f.p.shield + f.mod.ward);
  }
  // 24 的狂气：每 N 拍随机一件造物立刻触发
  if (f.hero.pas.k === 'surge' && f.t % f.hero.pas.v === 0) {
    f.surgeT = 1;
  }

  // 2) 状态结算
  for (const [side, obj] of [['p', f.p], ['e', f.e]]) {
    if (obj.poisonT > 0) {
      obj.hp -= obj.poison;
      obj.poisonT -= 1;
      ev.push({ s: side, k: 'poisonTick', v: obj.poison });
      if (!obj.poisonT) obj.poison = 0;
    }
    if (obj.burnT > 0) {
      hurt(f, obj, obj.burn);
      obj.burnT -= 1;
      ev.push({ s: side, k: 'burnTick', v: obj.burn });
      if (!obj.burnT) obj.burn = 0;
    }
  }
  if (checkOver(f)) return ev;

  // 3) 造物触发
  const queue = [];
  if (f.surgeT) {
    f.surgeT = 0;
    const active = f.items.filter((x) => x.cd > 0);
    if (active.length) queue.push(active[Math.floor(f.rnd() * active.length)]);
  }
  for (const it of f.items) {
    if (it.cd <= 0) continue;
    it.timer += 1;
    if (it.timer >= it.cd) { it.timer = 0; queue.push(it); }
  }
  let guard = 0;
  while (queue.length && guard++ < 24) {
    const it = queue.shift();
    const isFirst = !f.firstDone;
    f.firstDone = true;
    const mul = it.mul;
    for (const op of it.def.op) ev.push(...applyOp(f, 'p', op, mul, { src: it, aura: it.aura }));
    // 首次触发 ×2（二律背反）
    if (isFirst && f.pact.k === 'firstcrit') {
      // 追加一次等额伤害，简单直接
      const dmg = it.def.op.find((o) => o.k === 'dmg');
      if (dmg) {
        const extra = Math.round(dmg.v * mul + it.aura);
        hurt(f, f.e, extra);
        ev.push({ s: 'p', k: 'dmg', v: extra, crit: true, slot: it.slot });
      }
    }
  }
  if (checkOver(f)) return ev;

  // 4) 敌方技能
  for (const s of f.e.skills) {
    s.timer += 1;
    if (s.timer >= s.cd) {
      s.timer = 0;
      for (const op of s.op) {
        const isDmg = op.k === 'dmg' || op.k === 'poison' || op.k === 'burn';
        ev.push(...applyOp(f, 'e', op, isDmg ? f.atkMul : f.supMul, { src: {} }));
      }
    }
  }
  checkOver(f);
  return ev;
}

function checkOver(f) {
  if (f.over) return true;
  if (f.e.hp <= 0) { f.over = 'win'; f.win = true; return true; }
  if (f.p.hp <= 0) { f.over = 'lose'; f.win = false; return true; }
  // 打满还没分出胜负：按剩血百分比判，谁剩得多谁赢（同比例算玩家赢）
  if (f.t >= TUNING.beats) {
    const pr = f.p.hp / f.p.maxHp, er = f.e.hp / f.e.maxHp;
    f.win = pr >= er;
    f.over = f.win ? 'win' : 'lose';
    f.timeout = true;
    return true;
  }
  return false;
}

// 打完一整场（给模拟用）
function autoFight(f) {
  let guard = 0;
  while (!f.over && guard++ < TUNING.beats + 2) stepFight(f);
  return f;
}

// 战斗结束 → 结算回 run
function settle(run, f) {
  const goldGain = f.gold + (f.win ? TUNING.income[run.day] : 0) + f.mod.gold;
  run.gold += goldGain;
  run.history.push({ day: run.day, foe: f.foe.n, win: f.win, hp: Math.max(0, Math.round(f.p.hp)) });
  let cleared = false;
  if (f.win) {
    run.wins += 1;
    if (run.pact.k === 'grow') run.bonusHp += run.pact.v;
    run.day += 1;
    if (run.day > run.totalDays) { run.cleared = true; run.over = true; }
    else { pickFoe(run); rollShop(run, { free: true }); }
  } else {
    run.losses += 1;
    run.sane -= 1;
    // 最后一天打输也算散场（以前这里会顺手标成通关，白送一个「摊子开到最后」）
    if (run.sane <= 0 || run.day >= run.totalDays) {
      run.over = true;
    } else {
      run.day += 1;
      pickFoe(run);
      rollShop(run, { free: true });
    }
  }
  return { goldGain, cleared };
}

function scoreOf(run) {
  const day = Math.min(run.cleared ? run.totalDays : run.day - 1, run.totalDays);
  return day * 120 + Math.max(0, run.sane) * 60 + run.gold * 2 + (run.cleared ? 400 : 0);
}

// ---------------------------------------------------------------- 卡面文本（和 op 现算，保证一致）
const num = (v) => (Math.abs(v - Math.round(v)) < 1e-9 ? String(Math.round(v)) : v.toFixed(1));

function opText(op, mul = 1, aura = 0) {
  switch (op.k) {
    case 'dmg': {
      const v = num(Math.round(op.v * mul + aura));
      let t = `造成 ${v} 点伤害`;
      if (op.hits > 1) t += ` ${op.hits} 次`;
      if (op.pierce) t += '（无视护盾）';
      if (op.vsPoison) t += `；目标中毒时再造成 ${num(Math.round(op.vsPoison * mul))} 点`;
      if (op.leech) t += `；吸取 ${Math.round(op.leech * 100)}% 伤害为生命`;
      return t;
    }
    case 'poison': return `施加 ${num(op.v * mul)} 点中毒（${DOT_TURNS} 拍，无视护盾）`;
    case 'burn': return `施加 ${num(op.v * mul)} 点灼烧（${DOT_TURNS} 拍）`;
    case 'shield': return `获得 ${num(Math.round(op.v * mul))} 点护盾`;
    case 'heal': return `回复 ${num(Math.round(op.v * mul))} 点生命`;
    case 'gold': return `战斗中额外获得 ${num(Math.round(op.v * mul))} 金币`;
    case 'slow': return `敌方所有技能冷却 +${num(op.v * mul)}`;
    case 'haste': return `相邻造物冷却 -${num(op.v)}`;
    case 'charge': return `相邻造物计时立刻 +${num(op.v * mul)} 拍`;
    case 'aura': return `相邻造物伤害 +${num(Math.round(op.v * mul))}`;
    default: return '';
  }
}

function itemText(it, tier = 1) {
  const def = itemOf(it.key || it.id);
  const mul = TUNING.tierMul[tier];
  return def.op.map((o) => opText(o, mul)).join('；');
}

function cdText(cd) {
  return cd > 0 ? `${cd} 拍` : '光环';
}
return { TUNING, HEROES, ITEMS, WHEELS, WHEEL_FX, PACTS, FOES, SCHEDULE, itemOf, wheelOf, foeOf, heroOf, pactOf, ADJ, rngFrom, newRun, priceOf, rollShop, defOf, firstEmptySlot, canBuy, buy, sell, upgradeCost, upgrade, move, pickFoe, rawDps, foeStats, createFight, stepFight, autoFight, settle, scoreOf, opText, itemText, cdText };
})();

// ---- js/bazaar.js
const m_bazaar = await (async () => {
const { ART } = m_bazaar_art;
const C = m_bazaar_core;
const { TUNING, HEROES, PACTS, WHEEL_FX, REALM_COLOR } = m_bazaar_data;
// 《弥萨格大巴扎》界面层：集市、摊桌、自动战斗的表现。
// 规则本身全在 js/bazaar-core.js（node 里能跑，scripts/bazaar-sim.mjs 就是拿它做平衡的），
// 这里只负责把状态画出来、把点击翻译成动作。





const $ = (id) => document.getElementById(id);
const img = (src) => ART[src] || '';

const BEST_KEY = 'zjtt:bazaar:best';
const STATS_KEY = 'zjtt:bazaar:v1';

let run = null;
let fight = null;
let speed = 1;
let timer = 0;
let last = 0;
let playing = false;
let sel = -1;
let moving = false;
let sheetUid = 0;
let pactChoices = [];

// ---------------------------------------------------------------- 小工具
const fmt = (n) => Math.round(n).toLocaleString('zh-CN');
const pct = (a, b) => Math.max(0, Math.min(100, (a / b) * 100));

function toast(msg) {
  const el = $('log');
  if (!el) return;
  el.textContent = msg;
}

function heroColor(realm) { return REALM_COLOR[realm] || '#6ea8ff'; }

function starText(tier) { return '★'.repeat(tier) + '☆'.repeat(3 - tier); }

// 技能在当天的实际数值（怪物技能表是按当天强度归一过的，卡面必须显示真数）
function skillText(run_, foe, s) {
  const { atk, sup } = C.foeStats(run_);
  const parts = [];
  for (const op of s.op) {
    if (op.k === 'dmg') {
      const v = Math.round(op.v * atk * (op.hits ? 1 : 1));
      parts.push(op.hits > 1 ? `${v}×${op.hits}` : `${v}`);
    } else if (op.k === 'poison' || op.k === 'burn') parts.push(`${op.k === 'poison' ? '毒' : '烧'}${Math.round(op.v * atk)}`);
    else if (op.k === 'shield') parts.push(`盾${Math.round(op.v * sup)}`);
    else if (op.k === 'heal') parts.push(`疗${Math.round(op.v * sup)}`);
    else if (op.k === 'slow') parts.push(`缓${Math.round(op.v * sup)}`);
  }
  return parts.join(' · ');
}

// ---------------------------------------------------------------- 选人
function renderSetup() {
  const wrap = $('heroPick');
  wrap.innerHTML = HEROES.map((h) => `
    <button class="hcard" type="button" data-hero="${h.id}">
      <img src="${img(h.av)}" alt="">
      <div style="min-width:0">
        <div class="hn">${h.n}</div>
        <div class="hr">${h.realm} · ${h.role}</div>
        <div class="hp">${h.pas.txt}</div>
      </div>
    </button>`).join('');
  pactChoices = PACTS.slice().sort(() => Math.random() - 0.5).slice(0, 4);
  $('pactPick').innerHTML = pactChoices.map((p) => `
    <button class="pcard" type="button" data-pact="${p.id}">
      <img src="${img(p.im)}" alt="">
      <div style="min-width:0"><div class="pn">${p.n}</div><div class="pt">${p.txt}</div></div>
    </button>`).join('');
  wrap.onclick = (e) => {
    const b = e.target.closest('[data-hero]');
    if (!b) return;
    wrap.querySelectorAll('.hcard').forEach((x) => x.classList.toggle('on', x === b));
    $('setupTip').innerHTML = heroIntro(b.dataset.hero);
    $('pactHint').textContent = '再挑一份密契';
    decide();
  };
  $('pactPick').onclick = (e) => {
    const b = e.target.closest('[data-pact]');
    if (!b) return;
    $('pactPick').querySelectorAll('.pcard').forEach((x) => x.classList.toggle('on', x === b));
    decide();
  };
  $('btnStart').onclick = () => {
    const hid = $('heroPick').querySelector('.on')?.dataset.hero;
    const pid = $('pactPick').querySelector('.on')?.dataset.pact;
    if (!hid || !pid) return;
    startRun(hid, pid);
  };
}

function heroIntro(id) {
  const h = HEROES.find((x) => x.id === id);
  const w = WHEEL_FX[h.wheel.main];
  return `<b>${h.n}</b>｜${h.realm}｜${h.lore}<br>本命命轮「${h.wheel.n}」：${w.txt}。开局带 ${h.kit.map((k) => C.itemOf(k).n).join('、')}。`;
}

function decide() {
  const ok = $('heroPick').querySelector('.on') && $('pactPick').querySelector('.on');
  $('btnStart').disabled = !ok;
}

// ---------------------------------------------------------------- 开局
function startRun(heroId, pactId) {
  run = C.newRun({ seed: (Date.now() ^ (Math.random() * 1e9)) >>> 0, heroId, pactId });
  $('setup').classList.remove('on');
  $('app').hidden = false;
  sel = -1; moving = false;
  renderAll();
  toast(`第 1 天，先看看摊上有什么`);
}

// ---------------------------------------------------------------- 主界面
function renderAll() {
  if (!run) return;
  $('hDay').textContent = `第 ${Math.min(run.day, run.totalDays)} 天`;
  $('hDayMax').textContent = `/ ${run.totalDays}`;
  $('hSane').innerHTML = Array.from({ length: TUNING.sane }, (_, i) => `<i class="${i < run.sane ? '' : 'off'}">❤</i>`).join('');
  $('hGold').textContent = fmt(run.gold);
  renderFoe();
  renderBoard();
  renderWheels();
  renderShop();
  renderTrail();
  renderIntel();
  $('btnReroll').textContent = `刷新 ${TUNING.rerollCost + run.rerolls}`;
  $('btnReroll').disabled = run.gold < TUNING.rerollCost + run.rerolls;
}

function renderTrail() {
  const done = run.history;
  const cells = [];
  for (let d = 1; d <= run.totalDays; d++) {
    const h = done[d - 1];
    const cls = h ? (h.win ? 'win' : 'lose') : (d === run.day ? 'now' : '');
    const tip = h ? `第 ${d} 天 ${h.win ? '赢' : '输'}：${h.foe}` : `第 ${d} 天`;
    cells.push(`<span class="dot ${cls}" title="${tip}">${h ? (h.win ? '胜' : '负') : d}</span>`);
  }
  $('trail').innerHTML = cells.join('');
}

function renderIntel() {
  const foe = C.foeOf(run.foeId);
  const hero = run.hero;
  const p = run.pact;
  $('intel').innerHTML = `
    <div class="q">「${foe.desc}」</div>
    <div class="pills">
      <span>${hero.n}｜${hero.pas.txt}</span>
      <span>密契·${p.n}｜${p.txt}</span>
    </div>`;
}

function renderFoe() {
  const st = C.foeStats(run);
  const foe = st.foe;
  const weak = run.pact.k === 'weaken';
  $('foeBar').innerHTML = `
    <img src="${img(foe.im)}" alt="">
    <div class="fi">
      <div class="fn">${foe.n}<em class="${foe.rank === 'boss' ? 'boss' : ''}">${foe.rank === 'boss' ? '头目' : foe.rank === 'elite' ? '精英' : '杂兵'}${weak ? ' · 削弱' : ''}</em></div>
      <div class="fhp"><span>生命 ${fmt(st.maxHp)}</span><div class="bar"><i style="width:100%"></i></div></div>
      <div class="fsk">${foe.skills.map((s) => `<span>${s.n} ${skillText(run, foe, s)} · ${s.cd}拍</span>`).join('')}</div>
    </div>`;
}

function renderBoard() {
  const b = $('board');
  b.innerHTML = run.items.map((it, i) => {
    if (!it) return `<button class="slot ${sel === i ? 'sel' : ''}" type="button" data-slot="${i}" aria-label="空格"><span class="nm"><span>空格</span></span></button>`;
    const def = C.itemOf(it.key);
    const aura = def.cd === 0;
    return `<button class="slot has ${aura ? 'aura' : ''} ${sel === i ? 'sel' : ''} ${moving ? 'target' : ''}" type="button" data-slot="${i}">
      <img src="${img(def.im)}" alt="">
      <span class="st">${it.tier > 1 ? starText(it.tier) : ''}</span>
      <span class="cd">${aura ? '光环' : def.cd + ' 拍'}</span>
      <span class="nm"><span>${def.n}</span><i>${aura ? '相邻' : ''}</i></span>
      <span class="pick"></span>
    </button>`;
  }).join('');
  b.onclick = (e) => {
    const el = e.target.closest('[data-slot]');
    if (!el) return;
    const i = Number(el.dataset.slot);
    if (moving && sel >= 0) {
      const r = C.move(run, sel, i);
      moving = false;
      sel = -1;
      if (r === 'merge') toast('两件并成一件，升了一阶');
      else if (r === 'swap') toast('换了位置');
      renderAll();
      return;
    }
    if (!run.items[i]) return;
    sel = i;
    openSheet(run.items[i], i);
  };
}

function renderWheels() {
  const w = $('wheels');
  const parts = [`<span class="lab">命轮</span>`];
  for (const x of run.wheels) {
    const fx = WHEEL_FX[x.main];
    parts.push(`<button class="wh" type="button" data-wheel="${x.uid}"><img src="${img(x.im)}" alt=""><span><b>${x.n}</b><br>${fx ? fx.txt : ''}</span></button>`);
  }
  if (run.wheels.length < 3) parts.push(`<span class="wh empty">空 ${3 - run.wheels.length}</span>`);
  w.innerHTML = parts.join('');
  w.onclick = (e) => {
    const el = e.target.closest('[data-wheel]');
    if (el) openWheelSheet(Number(el.dataset.wheel));
  };
}

function renderShop() {
  const s = $('shop');
  if (!run.shop.length) { s.innerHTML = '<div class="tipbox">今天的摊位收完了，开战吧。</div>'; return; }
  s.innerHTML = run.shop.map((o, i) => {
    const def = C.defOf(o);
    const can = C.canBuy(run, i);
    const isW = o.kind === 'wheel';
    const rar = isW ? 'SR' : def.r;
    const txt = isW ? WHEEL_FX[def.main].txt : `${C.itemText(def, 1)}；${def.cd === 0 ? '光环，不触发' : def.cd + ' 拍一次'}`;
    return `<button class="card r-${rar} ${o.sold ? 'sold' : ''} ${!can && !o.sold ? 'poor' : ''}" type="button" data-offer="${i}">
      <img src="${img(def.im)}" alt="">
      <span class="cp ${run.gold < o.price ? 'no' : ''}">${o.price}</span>
      <span class="cn">${def.n}</span>
      <span class="ct">${txt}</span>
      <span class="r">${isW ? '命轮' : def.r}</span>
    </button>`;
  }).join('');
  s.onclick = (e) => {
    const el = e.target.closest('[data-offer]');
    if (!el) return;
    const i = Number(el.dataset.offer);
    const o = run.shop[i];
    if (!o || o.sold) return;
    if (!C.canBuy(run, i)) {
      toast(o.kind === 'wheel' ? '命轮最多戴三条' : (C.firstEmptySlot(run) < 0 ? '摊桌满了，先卖一件' : '金币不够'));
      return;
    }
    C.buy(run, i);
    renderAll();
  };
  $('shopHint').textContent = `还剩 ${run.shop.filter((x) => !x.sold).length} 个摊位`;
}

// ---------------------------------------------------------------- 详情
function openSheet(it, slot) {
  const def = C.itemOf(it.key);
  sheetUid = it.uid;
  $('sImg').src = img(def.im);
  $('sName').textContent = `${def.n}${it.tier > 1 ? ' ' + starText(it.tier) : ''}`;
  $('sMeta').textContent = `${def.r} · ${def.cd === 0 ? '光环，不自己出手' : '冷却 ' + def.cd + ' 拍'}`;
  $('sTxt').textContent = C.itemText(def, it.tier) + (def.cd === 0 ? '（光环只加成相邻的造物）' : '');
  const cost = C.upgradeCost(run, it);
  $('sUp').textContent = it.tier >= 3 ? '已满阶' : `升级 ${cost} 金`;
  $('sUp').disabled = it.tier >= 3 || run.gold < cost;
  $('sMove').textContent = '挪位置';
  const back = Math.max(1, Math.floor(def.cost * TUNING.sellRate * TUNING.tierMul[it.tier]));
  $('sSell').textContent = `卖出 +${back}`;
  $('sheet').classList.add('on');
  $('sUp').onclick = () => {
    if (!C.upgrade(run, it.uid)) { toast('金币不够'); return; }
    closeSheet(); renderAll();
  };
  $('sMove').onclick = () => { closeSheet(); moving = true; toast('点一个格子放下（同款同阶会合并）'); renderBoard(); };
  $('sSell').onclick = () => { C.sell(run, it.uid); closeSheet(); renderAll(); };
}

function openWheelSheet(uid) {
  const x = run.wheels.find((w) => w.uid === uid);
  if (!x) return;
  const fx = WHEEL_FX[x.main];
  sheetUid = uid;
  $('sImg').src = img(x.im);
  $('sName').textContent = x.n + (x.native ? '（本命）' : '');
  $('sMeta').textContent = x.native ? '本命命轮 · 不占商店名额' : '命轮 · 全局被动';
  $('sTxt').textContent = fx ? fx.txt : '';
  $('sUp').textContent = '—';
  $('sUp').disabled = true;
  $('sMove').textContent = '—';
  $('sMove').disabled = true;
  $('sSell').textContent = x.native ? '卖不了' : `卖出 +${Math.max(1, Math.floor(x.cost * TUNING.sellRate))}`;
  $('sSell').disabled = !!x.native;
  $('sSell').onclick = () => { C.sell(run, uid); closeSheet(); renderAll(); };
  $('sheet').classList.add('on');
}

function closeSheet() {
  $('sheet').classList.remove('on');
  $('sUp').disabled = false;
  $('sMove').disabled = false;
  $('sSell').disabled = false;
}

// ---------------------------------------------------------------- 战斗
function startFight() {
  fight = C.createFight(run);
  sel = -1; moving = false;
  closeSheet();
  $('battle').classList.add('on');
  paintFight();
  playing = true;
  speed = 1;
  $('btnSpeed').textContent = '×1';
  last = performance.now();
  timer = 0;
  requestAnimationFrame(loop);
}

function paintFight() {
  const f = fight;
  $('bFoeImg').src = img(f.foe.im);
  $('bFoeName').textContent = f.foe.n;
  $('bFoeHp').style.width = pct(f.e.hp, f.e.maxHp) + '%';
  $('bFoeHpTxt').textContent = `${fmt(Math.max(0, f.e.hp))} / ${fmt(f.e.maxHp)}`;
  $('bFoeShield').textContent = f.e.shield > 0 ? `盾 ${fmt(f.e.shield)}` : '';
  $('bFoeDot').textContent = dotText(f.e);
  $('bFoeSkills').innerHTML = f.e.skills.map((s, i) => `
    <span class="skill" id="sk${i}">${s.n} ${skillText(run, f.foe, s)}<i id="skb${i}"></i></span>`).join('');
  const cells = [];
  for (let i = 0; i < TUNING.slotN; i++) {
    const it = fight.items.find((x) => x.slot === i);
    if (!it) { cells.push(`<div class="slot" data-bslot="${i}"></div>`); continue; }
    cells.push(`<div class="slot has ${it.cd === 0 ? 'aura' : ''}" data-bslot="${i}">
      <img src="${img(it.def.im)}" alt="">
      <span class="st">${it.tier > 1 ? starText(it.tier) : ''}</span>
      <span class="cd">${it.cd === 0 ? '光环' : it.cd + ' 拍'}</span>
      <span class="nm"><span>${it.def.n}</span><i></i></span>
      <span class="prog"><i id="pg${it.slot}"></i></span>
    </div>`);
  }
  $('bBoard').innerHTML = cells.join('');
  $('bMyHp').style.width = pct(f.p.hp, f.p.maxHp) + '%';
  $('bMyHpTxt').textContent = `${fmt(Math.max(0, f.p.hp))} / ${fmt(f.p.maxHp)}`;
  $('bMyShield').textContent = f.p.shield > 0 ? `盾 ${fmt(f.p.shield)}` : '';
  $('bMyDot').textContent = dotText(f.p);
  $('log').textContent = '开战';
}

function dotText(o) {
  const a = [];
  if (o.poisonT > 0) a.push(`毒 ${fmt(o.poison)}`);
  if (o.burnT > 0) a.push(`烧 ${fmt(o.burn)}`);
  return a.join(' · ');
}

function paintBars() {
  const f = fight;
  $('bFoeHp').style.width = pct(f.e.hp, f.e.maxHp) + '%';
  $('bFoeHpTxt').textContent = `${fmt(Math.max(0, f.e.hp))} / ${fmt(f.e.maxHp)}`;
  $('bFoeShield').textContent = f.e.shield > 0 ? `盾 ${fmt(f.e.shield)}` : '';
  $('bFoeDot').textContent = dotText(f.e);
  $('bMyHp').style.width = pct(f.p.hp, f.p.maxHp) + '%';
  $('bMyHpTxt').textContent = `${fmt(Math.max(0, f.p.hp))} / ${fmt(f.p.maxHp)}`;
  $('bMyShield').textContent = f.p.shield > 0 ? `盾 ${fmt(f.p.shield)}` : '';
  $('bMyDot').textContent = dotText(f.p);
  for (const it of f.items) {
    const el = $(`pg${it.slot}`);
    if (el) el.style.width = it.cd > 0 ? Math.min(100, (it.timer / it.cd) * 100) + '%' : '0%';
  }
  f.e.skills.forEach((s, i) => {
    const el = $(`skb${i}`);
    if (el) el.style.width = Math.min(100, (s.timer / s.cd) * 100) + '%';
  });
}

function float(side, text, color) {
  const host = side === 'e' ? $('bFoeImg').parentElement : $('bMyHp').parentElement;
  const bar = host.getBoundingClientRect();
  const el = document.createElement('span');
  el.className = 'fx';
  el.textContent = text;
  el.style.color = color;
  el.style.left = '50%';
  el.style.top = '50%';
  document.body.appendChild(el);
  const r = el.getBoundingClientRect();
  el.style.position = 'fixed';
  el.style.left = Math.max(8, Math.min(window.innerWidth - r.width - 8, bar.left + bar.width / 2 - r.width / 2)) + 'px';
  el.style.top = Math.max(60, bar.top) + 'px';
  setTimeout(() => el.remove(), 760);
}

function applyEvents(ev) {
  let line = '';
  for (const e of ev) {
    if (e.k === 'dmg') {
      const side = e.s === 'p' ? 'e' : 'p';
      const col = e.s === 'p' ? (e.crit ? '#ffd166' : '#ff8f7a') : '#e8695f';
      float(side, (e.s === 'p' ? '' : '-') + fmt(e.v) + (e.crit ? ' 暴' : ''), col);
      if (e.s === 'p' && e.slot != null) flashSlot(e.slot);
      line = e.s === 'p' ? `你的造物造成 ${fmt(e.v)} 点伤害` : `${fight.foe.n} 打掉你 ${fmt(e.v)} 点`;
    } else if (e.k === 'shield') {
      float(e.s === 'p' ? 'p' : 'e', `+盾 ${fmt(e.v)}`, '#7fb2ff');
      line = e.s === 'p' ? `架起 ${fmt(e.v)} 点护盾` : `${fight.foe.n} 架盾 ${fmt(e.v)}`;
    } else if (e.k === 'heal') {
      float(e.s === 'p' ? 'p' : 'e', `+${fmt(e.v)}`, '#6fd39a');
      line = e.s === 'p' ? `回复 ${fmt(e.v)} 点生命` : `${fight.foe.n} 回了 ${fmt(e.v)} 点`;
    } else if (e.k === 'poison') {
      float(e.s === 'p' ? 'e' : 'p', `毒 ${fmt(e.v)}`, '#a98cff');
      line = e.s === 'p' ? `给对面灌了 ${fmt(e.v)} 点中毒` : `你中了 ${fmt(e.v)} 点毒`;
    } else if (e.k === 'burn') {
      float(e.s === 'p' ? 'e' : 'p', `烧 ${fmt(e.v)}`, '#ff9a5c');
      line = e.s === 'p' ? `点着了：${fmt(e.v)} 点灼烧` : `你被点着了 ${fmt(e.v)}`;
    } else if (e.k === 'gold') {
      line = `顺手摸走 ${fmt(e.v)} 金币`;
    } else if (e.k === 'slow') {
      line = `对面慢了 ${e.v} 拍`;
    } else if (e.k === 'haste' || e.k === 'charge') {
      line = e.k === 'haste' ? `旁边的造物转快了一点` : `旁边的造物被推了一把`;
      for (const s of (e.adj || [])) flashSlot(s);
    } else if (e.k === 'poisonTick' || e.k === 'burnTick') {
      if (e.v >= 1) float(e.s === 'p' ? 'e' : 'p', `-${fmt(e.v)}`, e.k === 'poisonTick' ? '#a98cff' : '#ff9a5c');
    }
  }
  if (line) $('log').textContent = line;
  paintBars();
}

function flashSlot(slot) {
  const el = document.querySelector(`[data-bslot="${slot}"]`);
  if (!el) return;
  el.classList.remove('fire');
  void el.offsetWidth;
  el.classList.add('fire');
}

function loop(now) {
  if (!playing) return;
  const dt = Math.min(120, now - last);
  last = now;
  timer += dt * speed;
  if (timer >= TUNING.beatMs) {
    timer -= TUNING.beatMs;
    const ev = C.stepFight(fight);
    if (ev.length) applyEvents(ev);
    else paintBars();
    if (fight.over) { endFight(); return; }
  }
  requestAnimationFrame(loop);
}

function endFight() {
  playing = false;
  const win = fight.win;
  const timeout = fight.timeout;
  $('log').textContent = win ? '对面撑不住了' : '你被打趴下了';
  paintBars();
  setTimeout(() => {
    const gain = C.settle(run, fight);
    if (win) toast(`赢了：+${gain.goldGain} 金`);
    $('battle').classList.remove('on');
    if (run.over) { showResult(); return; }
    renderAll();
    toast(win ? `第 ${run.day} 天，接着摆` : `输了一场，理智 ${run.sane}/${TUNING.sane}`);
    if (timeout) toast('打满 40 拍，按剩血比例判的');
  }, win ? 700 : 900);
}

function skipFight() {
  if (!fight || fight.over) return;
  let guard = 0;
  while (!fight.over && guard++ < TUNING.beats + 2) C.stepFight(fight);
  playing = false;
  paintBars();
  endFight();
}

// ---------------------------------------------------------------- 结算
function loadBest() {
  try { return Number(localStorage.getItem(BEST_KEY) || 0) || 0; } catch (e) { return 0; }
}
function saveBest(v) {
  try { localStorage.setItem(BEST_KEY, String(v)); } catch (e) { /* 无痕模式 */ }
}
// 存档摘要给 js/gamestats.js 读（个人中心的「游戏进度」）：只增不减的四个数 + 用过的命轮
function recordStats(score) {
  let s = {};
  try { s = JSON.parse(localStorage.getItem(STATS_KEY) || '{}') || {}; } catch (e) { s = {}; }
  const day = Math.min(run.cleared ? run.totalDays : run.day - 1, run.totalDays);
  const wheels = (s.wheels && typeof s.wheels === 'object') ? s.wheels : {};
  for (const w of run.wheels) wheels[w.id || w.key] = 1;   // 本命命轮只有 key（native+英雄），商店命轮才有 id
  const out = {
    best: Math.max(Number(s.best) || 0, score),
    day: Math.max(Number(s.day) || 0, day),
    runs: (Number(s.runs) || 0) + 1,
    wins: (Number(s.wins) || 0) + (run.cleared ? 1 : 0),
    pacts: Object.assign({}, (s.pacts && typeof s.pacts === 'object') ? s.pacts : {}, { [run.pact.id]: 1 }),
    heroes: Object.assign({}, (s.heroes && typeof s.heroes === 'object') ? s.heroes : {}, { [run.hero.id]: 1 }),
    wheels,
  };
  try { localStorage.setItem(STATS_KEY, JSON.stringify(out)); } catch (e) { /* 无痕模式 */ }
}

function showResult() {
  const score = C.scoreOf(run);
  const best0 = loadBest();
  const best = Math.max(best0, score);
  saveBest(best);
  recordStats(score);
  $('rTitle').textContent = run.cleared ? '摊子开到最后' : '散场';
  $('rSub').innerHTML = run.cleared
    ? `十二天走完，理智还剩 ${run.sane} 点。<br>${run.hero.n} 收摊回家。`
    : `第 ${Math.min(run.day, run.totalDays)} 天散场，理智见底。<br>${run.hero.n} 的摊子被人搬空了。`;
  $('rScore').textContent = fmt(score);
  $('rDays').textContent = Math.min(run.cleared ? run.totalDays : run.day - 1, run.totalDays);
  $('rGold').textContent = fmt(run.gold);
  $('rBest').textContent = fmt(best);
  $('result').classList.add('on');
}

function again() {
  $('result').classList.remove('on');
  $('app').hidden = true;
  $('setup').classList.add('on');
  run = null;
  $('btnStart').disabled = true;
  $('heroPick').querySelectorAll('.hcard').forEach((x) => x.classList.remove('on'));
  $('pactPick').querySelectorAll('.pcard').forEach((x) => x.classList.remove('on'));
  $('setupTip').textContent = '挑一个摊主。每人自带一件造物、一条本命命轮和一份脾气。';
  $('pactHint').textContent = '先挑人';
}

// ---------------------------------------------------------------- 绑定
$('btnReroll').onclick = () => {
  if (!C.rollShop(run)) { toast('金币不够刷新'); return; }
  renderAll();
};
$('btnFight').onclick = () => {
  if (!run.items.some(Boolean)) { toast('摊桌上什么都没有，先买点东西'); return; }
  startFight();
};
$('btnSpeed').onclick = () => {
  speed = speed === 1 ? 2 : speed === 2 ? 3 : 1;
  $('btnSpeed').textContent = '×' + speed;
};
$('btnSkip').onclick = skipFight;
$('btnAgain').onclick = again;
$('btnHelp').onclick = () => $('help').classList.add('on');
$('setupHelp').onclick = () => $('help').classList.add('on');
$('helpClose').onclick = () => $('help').classList.remove('on');
$('sheet').addEventListener('click', (e) => { if (e.target === $('sheet')) closeSheet(); });

// 选人界面默认打开
renderSetup();
$('setup').classList.add('on');
$('boot').classList.add('off');
return {  };
})();

